  (md5('clothsy:seller:sel_lilac')::uuid, 'the-lilac-edit', 'The Lilac Edit', 'Soft colour, easy silhouettes', 'A small Bengaluru label for people who like their wardrobe calm: soft colours, relaxed shapes and fabrics that feel good all day.', null, 'https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?w=1200&auto=format&fit=crop&q=80', 'Bengaluru', 'approved', true, true, 12900, 4.6, 2, 7),
  (md5('clothsy:seller:sel_mehr')::uuid, 'mehr-essentials', 'Mehr Essentials', 'Everyday basics in honest fabrics', 'Mehr Essentials is new to Clothsy: simple, well-made everyday pieces at fair prices.', null, 'https://images.unsplash.com/photo-1584917865442-de89df76afd3?w=1200&auto=format&fit=crop&q=80', 'New Delhi', 'approved', false, true, 2300, 4.4, 4, 7)
