insert into public.products (id, seller_id, handle, title, description,
  category, category_handles, tags, images, rating, review_count,
  is_tryon_eligible, is_featured, is_new, status, sort_rank) values
  (md5('clothsy:product:p_lavender_blazer')::uuid, md5('clothsy:seller:sel_noor')::uuid, 'lavender-blazer', 'Lavender Blazer', 'Tailored to perfection, this blazer adds a touch of elegance to any outfit. Crafted from premium breathable stretch twill with structured notch lapels, flap pockets, and a graceful tailored silhouette. Perfect for both casual and formal occasions.', 'Women', array['women', 'outerwear']::text[], array['Blazer', 'Outerwear', 'Women', 'Lavender', 'Featured']::text[], array['https://images.unsplash.com/photo-1591047139829-d91aecb6caea?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1584917865442-de89df76afd3?w=900&auto=format&fit=crop&q=80']::text[], 4.8, 120, true, true, true, 'live', 0),
  (md5('clothsy:product:p_minimal_overshirt')::uuid, md5('clothsy:seller:sel_rao')::uuid, 'minimal-overshirt', 'Minimal Overshirt', 'Clean-cut contemporary overshirt made with premium structured cotton twill. Features natural horn buttons, tailored collar, and clean dual utility chest pockets.', 'Men', array['men']::text[], array['Shirt', 'Overshirt', 'Men', 'Featured']::text[], array['https://images.unsplash.com/photo-1617137984095-74e4e5e3613f?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1507679799987-c73779587ccf?w=900&auto=format&fit=crop&q=80']::text[], 4.9, 88, true, true, true, 'live', 1),
  (md5('clothsy:product:p_lavender_hoodie')::uuid, md5('clothsy:seller:sel_lilac')::uuid, 'lavender-hoodie', 'Lavender Hoodie', 'Ultra-soft heavyweight brushed organic cotton fleece hoodie with relaxed dropped shoulders, double-layered hood, and ribbed trims.', 'Women', array['women']::text[], array['Hoodie', 'Sweater', 'Women', 'Lavender', 'Featured']::text[], array['https://images.unsplash.com/photo-1556905055-8f358a7a47b2?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1578587018452-892bacefd3f2?w=900&auto=format&fit=crop&q=80']::text[], 4.7, 145, true, true, true, 'live', 2),
  (md5('clothsy:product:p1')::uuid, md5('clothsy:seller:sel_noor')::uuid, 'silk-satin-maxi-dress', 'Silk Satin Maxi Dress', 'Cut on the bias for an effortless, figure-skimming drape. Crafted from premium 22-momme Mulberry silk satin with adjustable delicate straps and a subtle cowl neckline. Perfect for evenings and celebrations.', 'Dresses', array['women', 'dresses']::text[], array['Silk', 'Evening', 'Maxi', 'Dresses']::text[], array['https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1572804013309-59a88b7e92f1?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1496747611176-843222e1e57c?w=900&auto=format&fit=crop&q=80']::text[], 4.9, 184, true, true, true, 'live', 3),
  (md5('clothsy:product:p2')::uuid, md5('clothsy:seller:sel_rao')::uuid, 'linen-tailored-blazer', 'Linen Tailored Blazer', 'Structured yet lightweight, crafted from pure Normandy flax linen. Features structured lapels, tortoiseshell buttons, and a relaxed tailored fit that pairs effortlessly with tailored trousers or slip skirts.', 'Outerwear', array['women', 'outerwear']::text[], array['Linen', 'Blazer', 'Tailored', 'Outerwear']::text[], array['https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1591047139829-d91aecb6caea?w=900&auto=format&fit=crop&q=80']::text[], 4.8, 96, true, true, true, 'live', 4),
  (md5('clothsy:product:p3')::uuid, md5('clothsy:seller:sel_lilac')::uuid, 'pleated-slip-midi-gown', 'Pleated Slip Midi Gown', 'Delicate micro-accordion pleats enhance every movement. Finished with a subtle asymmetric hemline and graceful silhouette.', 'Dresses', array['women', 'dresses']::text[], array['Pleated', 'Midi', 'Dresses']::text[], array['https://images.unsplash.com/photo-1539109136881-3be0616acf4b?w=900&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1509631179647-0177331693ae?w=900&auto=format&fit=crop&q=80']::text[], 4.7, 65, true, true, false, 'live', 5),
  (md5('clothsy:product:p4')::uuid, md5('clothsy:seller:sel_mehr')::uuid, 'cashmere-blend-knit-top', 'Cashmere Blend Knit Top', 'Supremely soft Mongolian cashmere spun with organic cotton. A timeless mock-neck silhouette designed for transitional season layering.', 'Tops', array['tops']::text[], array['Knitwear', 'Cashmere', 'Tops']::text[], array['https://images.unsplash.com/photo-1576995853123-5a10305d93c0?w=900&auto=format&fit=crop&q=80']::text[], 4.9, 112, true, false, true, 'live', 6),
  (md5('clothsy:product:p5')::uuid, md5('clothsy:seller:sel_noor')::uuid, 'sculpted-leather-tote', 'Sculpted Leather Tote', 'Full-grain Italian calfskin leather handcrafted with architectural curved handles and gold-tone custom hardware.', 'Bags', array['bags']::text[], array['Leather', 'Bags', 'Accessories']::text[], array['https://images.unsplash.com/photo-1584917865442-de89df76afd3?w=900&auto=format&fit=crop&q=80']::text[], 4.9, 78, false, true, false, 'live', 7),
  (md5('clothsy:product:p6')::uuid, md5('clothsy:seller:sel_rao')::uuid, 'minimalist-ankle-strap-heels', 'Minimalist Ankle Strap Heels', '75mm sculptural stiletto heel with delicate ankle strap and cushioned memory foam insole for all-evening comfort.', 'Shoes', array['shoes']::text[], array['Shoes', 'Heels', 'Footwear']::text[], array['https://images.unsplash.com/photo-1543163521-1bf539c55dd2?w=900&auto=format&fit=crop&q=80']::text[], 4.8, 53, false, false, true, 'live', 8)
;

